// Filtra los vencidos (fechaEstimada < hoy) y arma un resumen por WhatsApp
// para los numeros de ADMIN_WHATSAPP (editar abajo).
const ADMIN_WHATSAPP = ['PEGAR_NUMERO_ADMIN'];
const hoy = new Date().toISOString().slice(0, 10);
const atrasados = [];
for (const item of $input.all()) {
  const doc = item.json.document;
  if (!doc) continue;
  const f = doc.fields || {};
  const fecha = f.proveedor && f.proveedor.mapValue && f.proveedor.mapValue.fields && f.proveedor.mapValue.fields.fechaEstimada ? f.proveedor.mapValue.fields.fechaEstimada.stringValue : null;
  if (fecha && fecha < hoy) {
    atrasados.push(`\u2022 *${f.numero ? f.numero.stringValue : '?'}* ${f.obraNombre ? f.obraNombre.stringValue : ''} \u2014 estimado ${fecha} (${f.proveedor.mapValue.fields.nombre ? f.proveedor.mapValue.fields.nombre.stringValue : ''})`);
  }
}
if (!atrasados.length) return [];
const texto = `\u23F0 *Pedidos de Obra \u2014 ${atrasados.length} pedido(s) ATRASADO(s)*\n\n${atrasados.join('\n')}\n\nhttps://skyterrasl.github.io/pedidos-obra/`;
return ADMIN_WHATSAPP.filter(Boolean).map((n) => ({ json: { number: String(n).replace(/[^0-9]/g, ''), text: texto } }));
